9	export type ScenarioResult = { premium: number };
10	
11	export type ScenarioOutcome = { results: ScenarioResult[] };
12	
13	type Item = { type: string };
14	
15	type Scenario = { steps: { items: Item[] }[] };
16	
17	const basePremiumOf = (item: Item): number =>
18	  item.type === "amulet" ? AMULET_BASE_PREMIUM : SWORD_BASE_PREMIUM;
19	
20	// Adds the surcharge as a separate term rather than scaling by 1.1, because
21	// `100 * 1.1` is 115.00000000000001 in binary floating point.
22	const withFirstInsuranceSurcharge = (amount: number): number =>
23	  amount + amount * FIRST_INSURANCE_SURCHARGE_RATE;
24	
25	const quotePremium = (items: Item[]): number => {
26	  const basePremium = items.reduce<number>(
27	    (total, item) => total + basePremiumOf(item),
28	    0,
29	  );
30	
31	  return withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
32	};
33	
34	export const runScenario = (scenario: unknown): ScenarioOutcome => {
35	  const { steps } = scenario as Scenario;
36	
37	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
38	
39	  return { results };
40	};
